package com.chuckerteam.chucker.internal.grpc.format

import com.google.gson.JsonArray
import com.google.gson.JsonElement
import com.google.gson.JsonNull
import com.google.gson.JsonObject
import com.google.gson.JsonPrimitive
import okio.ByteString.Companion.toByteString
import java.lang.reflect.Method
import java.lang.reflect.Modifier
import java.util.concurrent.ConcurrentHashMap

/**
 * Reads messages generated by protoc for Java, both `protobuf-javalite` and `protobuf-java`,
 * and converts them to their proto3 JSON representation.
 *
 * Lite messages carry no descriptors, so the schema is recovered from the generated code instead:
 * each field has a `FOO_BAR_FIELD_NUMBER` constant, which gives its number and proto name, and
 * typed accessors such as `getFooBar()`, `getFooBarList()`, `getFooBarMap()` and `hasFooBar()`.
 * Fields that aren't known to the generated class are decoded from the wire bytes and shown as
 * `#<field number>`.
 *
 * Only reflection is used, so Chucker doesn't depend on protobuf at all.
 */
internal object ProtobufMessageReader {
    private const val MESSAGE_LITE = "com.google.protobuf.MessageLite"
    private const val BYTE_STRING = "com.google.protobuf.ByteString"
    private const val FIELD_NUMBER_SUFFIX = "_FIELD_NUMBER"
    private const val GETTER_PREFIX = "get"
    private const val HAZZER_PREFIX = "has"
    private const val UNRECOGNIZED = "UNRECOGNIZED"
    private const val MAX_DEPTH = 64

    private val classInfos = ConcurrentHashMap<Class<*>, ClassInfo>()

    fun isMessage(value: Any): Boolean = Reflection.isSubtypeOf(value.javaClass, MESSAGE_LITE)

    /**
     * Returns the JSON representation of [message], or null when it isn't a protobuf message.
     * Well-known types such as `Timestamp` aren't represented by JSON objects.
     */
    fun read(message: Any): JsonElement? {
        if (!isMessage(message)) return null
        return readMessage(message, depth = 0)
    }

    private fun readMessage(
        message: Any,
        depth: Int,
    ): JsonElement {
        if (depth > MAX_DEPTH) return JsonPrimitive(message.toString())
        WellKnownTypes.read(message, depth)?.let { return it }

        val info = classInfos.getOrPut(message.javaClass) { ClassInfo.of(message.javaClass) }
        val json = JsonObject()
        for (field in info.fields) {
            field.read(message, depth)?.let { json.add(field.jsonName, it) }
        }
        for ((key, value) in unknownFields(message, info).entrySet()) {
            json.add(key, value)
        }
        return json
    }

    // Unknown fields are only serialized when there are some, which is rare.
    private fun unknownFields(
        message: Any,
        info: ClassInfo,
    ): JsonObject {
        val unknownFieldSet = info.unknownFieldSet(message)
        val size = unknownFieldSet?.let { Reflection.call(it, "getSerializedSize") as? Int } ?: 0
        val fields =
            if (size > 0) {
                (Reflection.call(message, "toByteArray") as? ByteArray)?.let(RawProtoDecoder::decodeFields).orEmpty()
            } else {
                emptyList()
            }
        return RawProtoDecoder.toJsonObject(fields.filter { it.first !in info.fieldNumbers })
    }

    private fun convert(
        value: Any?,
        depth: Int,
    ): JsonElement =
        when {
            value == null -> JsonNull.INSTANCE
            value is String -> JsonPrimitive(value)
            value is Boolean -> JsonPrimitive(value)
            value is Number -> ProtoJson.number(value)
            value is Enum<*> -> JsonPrimitive(value.name)
            value is List<*> -> JsonArray().apply { value.forEach { add(convert(it, depth)) } }
            value is Map<*, *> ->
                JsonObject().apply { value.forEach { (key, item) -> add(key.toString(), convert(item, depth)) } }
            isByteString(value) -> JsonPrimitive(byteStringToBase64(value))
            isMessage(value) -> readMessage(value, depth + 1)
            else -> JsonPrimitive(value.toString())
        }

    private fun isByteString(value: Any): Boolean = Reflection.isSubtypeOf(value.javaClass, BYTE_STRING)

    fun byteStringToBase64(value: Any): String {
        val bytes = Reflection.call(value, "toByteArray") as ByteArray
        return bytes.toByteString().base64()
    }

    private fun isDefaultValue(value: Any?): Boolean =
        when (value) {
            null -> true
            is String -> value.isEmpty()
            is Boolean -> !value
            is Float -> value == 0f
            is Double -> value == 0.0
            is Number -> value.toLong() == 0L
            is Enum<*> -> value.ordinal == 0 && value.name != UNRECOGNIZED
            is List<*> -> value.isEmpty()
            is Map<*, *> -> value.isEmpty()
            else -> isByteString(value) && Reflection.call(value, "isEmpty") == true
        }

    private fun Any?.isUnrecognizedEnum(): Boolean = this is Enum<*> && name == UNRECOGNIZED

    private enum class Kind { SINGULAR, REPEATED, MAP }

    private class FieldInfo(
        val number: Int,
        val jsonName: String,
        val kind: Kind,
        val getter: Method,
        // hasFoo(), when the field tracks presence.
        val hazzer: Method?,
        // getFooValue(), getFooValueList() or getFooValueMap() for enum fields.
        val enumNumberGetter: Method?,
    ) {
        fun read(
            message: Any,
            depth: Int,
        ): JsonElement? {
            val value = getter.invoke(message)
            val isPresent = hazzer?.invoke(message) as? Boolean ?: !isDefaultValue(value)
            if (!isPresent) return null
            return when (kind) {
                Kind.SINGULAR -> readSingular(message, value, depth)
                Kind.REPEATED -> readRepeated(message, value as List<*>, depth)
                Kind.MAP -> readMap(message, value as Map<*, *>, depth)
            }
        }

        // An enum value unknown to the client is UNRECOGNIZED, so its number is shown instead.
        private fun readSingular(
            message: Any,
            value: Any?,
            depth: Int,
        ): JsonElement =
            if (value.isUnrecognizedEnum() && enumNumberGetter != null) {
                convert(enumNumberGetter.invoke(message), depth)
            } else {
                convert(value, depth)
            }

        private fun readRepeated(
            message: Any,
            values: List<*>,
            depth: Int,
        ): JsonElement {
            val numbers = enumNumbers(message, values) as? List<*>
            return JsonArray().apply {
                values.forEachIndexed { index, item -> add(convertItem(item, numbers?.getOrNull(index), depth)) }
            }
        }

        private fun readMap(
            message: Any,
            values: Map<*, *>,
            depth: Int,
        ): JsonElement {
            val numbers = enumNumbers(message, values.values) as? Map<*, *>
            return JsonObject().apply {
                values.forEach { (key, item) -> add(key.toString(), convertItem(item, numbers?.get(key), depth)) }
            }
        }

        // Only fetched when needed, since it allocates a new collection.
        private fun enumNumbers(
            message: Any,
            values: Collection<*>,
        ): Any? = enumNumberGetter?.takeIf { values.any { it.isUnrecognizedEnum() } }?.invoke(message)

        private fun convertItem(
            item: Any?,
            enumNumber: Any?,
            depth: Int,
        ): JsonElement =
            if (item.isUnrecognizedEnum() && enumNumber != null) {
                convert(enumNumber, depth)
            } else {
                convert(item, depth)
            }
    }

    private class ClassInfo(
        val fields: List<FieldInfo>,
        private val unknownFieldsAccessor: ((Any) -> Any?)?,
    ) {
        val fieldNumbers: Set<Int> = fields.mapTo(HashSet()) { it.number }

        fun unknownFieldSet(message: Any): Any? = unknownFieldsAccessor?.invoke(message)

        companion object {
            fun of(clazz: Class<*>): ClassInfo {
                val methods = clazz.methods.filter { it.parameterTypes.isEmpty() && !Modifier.isStatic(it.modifiers) }
                val getters =
                    methods
                        .filter { it.name.startsWith(GETTER_PREFIX) }
                        .associateBy { normalize(it.name.removePrefix(GETTER_PREFIX)) }
                val hazzers =
                    methods
                        .filter { it.name.startsWith(HAZZER_PREFIX) }
                        .filter { it.returnType == Boolean::class.javaPrimitiveType }
                        .associateBy { normalize(it.name.removePrefix(HAZZER_PREFIX)) }

                val fields =
                    clazz.fields
                        .filter { it.isFieldNumberConstant() }
                        .mapNotNull { constant ->
                            val protoName = constant.name.removeSuffix(FIELD_NUMBER_SUFFIX).lowercase()
                            fieldInfo(constant.getInt(null), protoName, getters, hazzers)
                        }.sortedBy { it.number }
                return ClassInfo(fields, unknownFieldsAccessor(clazz))
            }

            private fun java.lang.reflect.Field.isFieldNumberConstant(): Boolean =
                Modifier.isStatic(modifiers) &&
                    type == Int::class.javaPrimitiveType &&
                    name.endsWith(FIELD_NUMBER_SUFFIX)

            private fun fieldInfo(
                number: Int,
                protoName: String,
                getters: Map<String, Method>,
                hazzers: Map<String, Method>,
            ): FieldInfo? {
                val key = normalize(protoName)
                val jsonName = ProtoJson.jsonName(protoName)
                val mapGetter = getters[key + "map"]?.takeIf { Map::class.java.isAssignableFrom(it.returnType) }
                val listGetter = getters[key + "list"]?.takeIf { List::class.java.isAssignableFrom(it.returnType) }
                val getter = getters[key]
                return when {
                    mapGetter != null ->
                        FieldInfo(number, jsonName, Kind.MAP, mapGetter, null, getters[key + "valuemap"])
                    listGetter != null ->
                        FieldInfo(number, jsonName, Kind.REPEATED, listGetter, null, getters[key + "valuelist"])
                    getter != null -> {
                        val numberGetter =
                            getters[key + "value"]?.takeIf { it.returnType == Int::class.javaPrimitiveType }
                        FieldInfo(number, jsonName, Kind.SINGULAR, getter, hazzers[key], numberGetter)
                    }
                    else -> null
                }
            }

            // Lite keeps unknown fields in a protected field, protobuf-java exposes a getter.
            private fun unknownFieldsAccessor(clazz: Class<*>): ((Any) -> Any?)? {
                val field = Reflection.findField(clazz, "unknownFields")
                if (field != null) return { message -> field.get(message) }
                val getter = runCatching { clazz.getMethod("getUnknownFields") }.getOrNull() ?: return null
                return { message -> getter.invoke(message) }
            }

            // Field names and accessor names only differ in case and underscores.
            private fun normalize(name: String): String = name.replace("_", "").lowercase()
        }
    }

    /**
     * The well-known types have a special JSON representation, see
     * https://protobuf.dev/programming-guides/json/#any.
     */
    private object WellKnownTypes {
        private const val PACKAGE = "com.google.protobuf."
        private val WRAPPERS =
            setOf("DoubleValue", "FloatValue", "Int64Value", "Int32Value", "BoolValue", "StringValue", "BytesValue")

        fun read(
            message: Any,
            depth: Int,
        ): JsonElement? {
            val className = message.javaClass.name
            if (!className.startsWith(PACKAGE)) return null
            val simpleName = className.removePrefix(PACKAGE)
            return when (simpleName) {
                "Timestamp" -> JsonPrimitive(ProtoJson.timestamp(seconds(message), nanos(message)))
                "Duration" -> JsonPrimitive(ProtoJson.duration(seconds(message), nanos(message)))
                in WRAPPERS -> convert(Reflection.call(message, "getValue"), depth)
                "UInt64Value" -> ProtoJson.unsigned(long(message, "getValue"))
                "UInt32Value" -> ProtoJson.unsigned(int(message, "getValue"))
                "Struct" -> convert(Reflection.call(message, "getFieldsMap"), depth)
                "ListValue" -> convert(Reflection.call(message, "getValuesList"), depth)
                "Value" -> readValue(message, depth)
                "FieldMask" -> readFieldMask(message)
                "Any" -> readAny(message)
                else -> null
            }
        }

        private fun readValue(
            message: Any,
            depth: Int,
        ): JsonElement =
            when ((Reflection.call(message, "getKindCase") as Enum<*>).name) {
                "NUMBER_VALUE" -> convert(Reflection.call(message, "getNumberValue"), depth)
                "STRING_VALUE" -> convert(Reflection.call(message, "getStringValue"), depth)
                "BOOL_VALUE" -> convert(Reflection.call(message, "getBoolValue"), depth)
                "STRUCT_VALUE" -> convert(Reflection.call(message, "getStructValue"), depth)
                "LIST_VALUE" -> convert(Reflection.call(message, "getListValue"), depth)
                else -> JsonNull.INSTANCE
            }

        private fun readFieldMask(message: Any): JsonElement {
            val paths = Reflection.call(message, "getPathsList") as List<*>
            return JsonPrimitive(
                paths.joinToString(",") { path ->
                    path.toString().split('.').joinToString(".") { ProtoJson.jsonName(it) }
                },
            )
        }

        // Without a type registry the packed message can only be decoded without a schema.
        private fun readAny(message: Any): JsonElement {
            val bytes = Reflection.call(Reflection.call(message, "getValue")!!, "toByteArray") as ByteArray
            return JsonObject().apply {
                addProperty("@type", Reflection.call(message, "getTypeUrl") as String)
                add("value", RawProtoDecoder.decode(bytes) ?: JsonPrimitive(bytes.toByteString().base64()))
            }
        }

        private fun seconds(message: Any): Long = long(message, "getSeconds")

        private fun nanos(message: Any): Int = int(message, "getNanos")

        private fun long(
            message: Any,
            getter: String,
        ): Long = Reflection.call(message, getter) as Long

        private fun int(
            message: Any,
            getter: String,
        ): Int = Reflection.call(message, getter) as Int
    }
}
